import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { supabase } from '../lib/supabase';

const AuthContext = createContext();

export function AuthProvider({ children }) {
  const [user, setUser] = useState(null);
  const [staff, setStaff] = useState(null);
  const [loading, setLoading] = useState(true);
  const [activeStoreId, setActiveStoreId] = useState(null);
  const [availableStores, setAvailableStores] = useState([]);
  const [subscriptionStatus, setSubscriptionStatus] = useState(null);
  const [trialDaysLeft, setTrialDaysLeft] = useState(null);
  const [isLocked, setIsLocked] = useState(false);

  const loadUser = useCallback(async () => {
    const saved = localStorage.getItem('local_user');
    if (!saved) {
      setUser(null); setStaff(null); setActiveStoreId(null);
      setAvailableStores([]); setLoading(false);
      return;
    }
    const parsed = JSON.parse(saved);
    setUser(parsed);

    try {
      const allStores = JSON.parse(localStorage.getItem('bwanali_stores') || '[]');
      const userStore = allStores.find(s => s.id === parsed.store_id);
      const storesList = userStore ? [userStore] : allStores;
      setAvailableStores(storesList);

      const activeId = parsed.store_id || (allStores.length ? allStores[0].id : null);
      setActiveStoreId(activeId);

      const staffMember = {
        ...parsed,
        full_name: parsed.full_name || 'User',
        role: parsed.role || 'admin',
        is_active: parsed.is_active !== false,
        store: userStore || storesList[0],
      };
      setStaff(staffMember);

      const store = userStore || allStores[0];
      if (store) {
        setSubscriptionStatus(store.subscription_status);
        setIsLocked(store.locked || false);
        if (store.subscription_status === 'trialing' && store.trial_started_at) {
          const end = new Date(store.trial_started_at);
          end.setDate(end.getDate() + 3);
          const left = Math.max(0, Math.ceil((end - new Date()) / 86400000));
          setTrialDaysLeft(left);
        }
      }
    } catch (e) { console.error(e); }
    finally { setLoading(false); }
  }, []);

  useEffect(() => {
    loadUser();
    window.addEventListener('auth-change', loadUser);
    window.addEventListener('focus', loadUser);
    return () => {
      window.removeEventListener('auth-change', loadUser);
      window.removeEventListener('focus', loadUser);
    };
  }, [loadUser]);

  const checkSubscription = useCallback(async (storeId) => {
    const allStores = JSON.parse(localStorage.getItem('bwanali_stores') || '[]');
    const store = allStores.find(s => s.id === storeId);
    if (store) {
      setSubscriptionStatus(store.subscription_status);
      setIsLocked(store.locked || false);
    }
  }, []);

  const signIn = async (email, password) => {
    const { data, error } = await supabase.auth.signInWithPassword({ email, password });
    if (error) return { error };
    return {};
  };

  const signOut = async () => {
    await supabase.auth.signOut();
    setUser(null); setStaff(null); setActiveStoreId(null); setAvailableStores([]);
  };

  const role = staff?.role;
  const isAdmin = role === 'admin';
  const isManager = role === 'manager' || isAdmin;
  const hasActive = subscriptionStatus === 'active' || (subscriptionStatus === 'trialing' && !isLocked);

  return (
    <AuthContext.Provider
      value={{
        user, staff, setStaff, storeId: activeStoreId, availableStores,
        switchStore: (id) => { setActiveStoreId(id); loadUser(); },
        signIn, signOut, loading,
        isAdmin, isManager,
        canManageInventory: isAdmin || role === 'manager',  // only admin/manager can edit products
        canDelete: isAdmin,   // only admin can delete things
        subscriptionStatus, trialDaysLeft,
        hasActiveSubscription: hasActive,
        isLocked, checkSubscription,
        reloadStaff: () => loadUser(),
      }}
    >
      {children}
    </AuthContext.Provider>
  );
}

export const useAuth = () => useContext(AuthContext);
